-- Native exponential references, independently evaluated with MPFR at 256 bits.
-- Each input is parsed to qfloat components before its reference is computed; expectations retain 66 decimal digits.
-- Cases cover reduction boundaries near k*ln(2) +/- ln(2)/2 and finite arguments from -600 to 600.
CREATE TABLE IF NOT EXISTS qfloat_cases (
    name TEXT PRIMARY KEY,
    operation TEXT NOT NULL,
    input TEXT NOT NULL,
    expected TEXT NOT NULL,
    precision INTEGER NOT NULL DEFAULT 29 CHECK (precision BETWEEN 1 AND 31),
    enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1))
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS qfloat_cases_operation ON qfloat_cases(operation,name);

INSERT INTO test_case_runner(module,source,parent,table_name,operation) VALUES (
    'qfloat.exp_references','tests/qfloat/test_qfloat.c','tests.test_qf_exp_references','qfloat_cases','exp')
ON CONFLICT(module) DO UPDATE SET table_name=excluded.table_name,operation=excluded.operation;

